#!/usr/bin/env python3
"""Remove JavaScript from HTML while preserving untouched source formatting."""
import html
import re
import sys
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import unquote

URL_ATTRIBUTES = frozenset('href src action formaction xlink:href data poster background cite manifest codebase archive longdesc usemap profile'.split())
DROP_CONTENT = frozenset({'script', 'applet', 'object', 'embed'})
DROP_TAG = frozenset({'base'})
CSS_BAD = re.compile(r'expression\s*\(|behavior\s*:|-moz-binding\s*:|@import\b|url\s*\(\s*[\"\']?\s*(?:javascript|vbscript|data\s*:\s*text/html)\s*:', re.I)
TAG = re.compile(r'<!--.*?-->|<![^>]*>|<\?[^>]*>|</?[A-Za-z][^>]*>', re.S)
ATTR = re.compile(r'''([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?''')


def unsafe_url(value):
    value = html.unescape(value)
    for _ in range(3):
        decoded = unquote(value)
        if decoded == value:
            break
        value = decoded
    value = re.sub(r'[\x00-\x20\x7f]+', '', value).casefold()
    if value.startswith(('javascript:', 'vbscript:')):
        return True
    return value.startswith('data:') and not value.startswith(('data:image/', 'data:audio/', 'data:video/', 'data:font/'))


def sanitize_tag(raw):
    if raw.startswith(('<!--', '<!', '<?')):
        return raw
    end = raw.startswith('</')
    match = re.match(r'<(/?)\s*([^\s/>]+)', raw)
    if not match:
        return raw
    closing, tag = match.groups()
    tag = tag.lower()
    if end:
        return raw if tag not in DROP_CONTENT and tag not in DROP_TAG else ''
    if tag in DROP_TAG:
        return ''
    if tag in DROP_CONTENT:
        return raw
    self_closing = raw.rstrip().endswith('/>')
    attrs = []
    for match in ATTR.finditer(raw[match.end():].rstrip('>/')):
        name, double, single, unquoted = match.groups()
        key = name.lower()
        value = double if double is not None else single if single is not None else unquoted
        if key.startswith('on') or (key == 'srcdoc'):
            continue
        if value is not None and key in URL_ATTRIBUTES and unsafe_url(value):
            continue
        if value is not None and key == 'style':
            value = CSS_BAD.sub('', value)
        attrs.append((key, value))
    # Preserve the original tag exactly if no filtering or CSS edit is necessary.
    original_attrs = [(m.group(1).lower(), next((v for v in m.groups()[1:] if v is not None), None)) for m in ATTR.finditer(raw[match.end():].rstrip('>/'))]
    if attrs == original_attrs and not any(v is not None and k == 'style' and CSS_BAD.search(v) for k, v in attrs):
        return raw
    result = ['<' + tag]
    for key, value in attrs:
        if value is None:
            result.append(' ' + key)
        else:
            result.append(' ' + key + '="' + html.escape(value, quote=True) + '"')
    result.append('/>' if self_closing else '>')
    return ''.join(result)


def sanitize(source):
    pieces = []
    cursor = 0
    suppressed = []
    for match in TAG.finditer(source):
        raw = match.group()
        if not suppressed:
            pieces.append(source[cursor:match.start()])
        cursor = match.end()
        if raw.startswith(('<!--', '<!', '<?')):
            if not suppressed:
                pieces.append(raw)
            continue
        tag_match = re.match(r'<(/?)\s*([^\s/>]+)', raw)
        if not tag_match:
            if not suppressed:
                pieces.append(raw)
            continue
        closing, name = tag_match.groups()
        name = name.lower()
        if suppressed:
            if closing and name == suppressed[-1]:
                suppressed.pop()
            elif not closing and name in DROP_CONTENT and not raw.rstrip().endswith('/>'):
                suppressed.append(name)
            continue
        if not closing and name in DROP_CONTENT:
            if not raw.rstrip().endswith('/>'):
                suppressed.append(name)
            continue
        pieces.append(sanitize_tag(raw))
    if not suppressed:
        pieces.append(source[cursor:])
    return ''.join(pieces)


def main():
    if len(sys.argv) < 2:
        print('Usage: filter.py HTML_FILE', file=sys.stderr)
        return 2
    path = Path(sys.argv[1])
    with path.open(encoding='utf-8', errors='surrogateescape', newline='') as stream:
        source = stream.read()
    result = sanitize(source)
    with path.open('w', encoding='utf-8', errors='surrogateescape', newline='') as stream:
        stream.write(result)
    return 0

if __name__ == '__main__':
    sys.exit(main())
